    \quad\text{and}\quad
    \boldsymbol{\beta}_{j,1}^\top\boldsymbol{\theta}_{i,1}
    =
    \boldsymbol{\beta}_{j,2}^\top\boldsymbol{\theta}_{i,2},
    \qquad \forall i\in\mathcal{I},\ \forall j\in\mathcal{J}_0.
\end{equation*}
Because $|\mathcal{J}_0|\ge K+1$, one may select $K$ indices from $\mathcal{J}_0$ to construct full-rank
$K\times K$ matrices $B_l$ whose rows are $\boldsymbol{\beta}_{j,l}$, $l\in\{1,2\}$.
The preceding identity implies
\begin{equation*}
    B_1\boldsymbol{\theta}_{i,1} = B_2\boldsymbol{\theta}_{i,2},
    \qquad \forall i\in\mathcal{I}.
\end{equation*}
Let $O=B_1^{-1}B_2$. Then $\boldsymbol{\theta}_{i,1}=O\boldsymbol{\theta}_{i,2}$ for all $i\in\mathcal{I}$, and hence $\Theta_1=\Theta_2O^\top$.
Assumption~2 also gives $I^{-1}\Theta_l^\top\Theta_l=I_{K\times K}$ for $l\in\{1,2\}$.  
Therefore,
\begin{equation*}
    I_{K\times K}
    =
    I^{-1}\Theta_1^\top\Theta_1
    =
    O(I^{-1}\Theta_2^\top\Theta_2)O^\top
    =
    OO^\top,
\end{equation*}
showing that $O$ is orthogonal. Thus, we have
\begin{equation*}
    \alpha_{j,1}=\alpha_{j,2},
    \qquad
    \boldsymbol{\beta}_{j,1}=O\boldsymbol{\beta}_{j,2},
    \qquad
    \boldsymbol{\theta}_{i,1}=O\boldsymbol{\theta}_{i,2},
    \quad \forall i\in\mathcal{I},\; \forall j \in \mathcal{J}_0.
\end{equation*}

Now consider $j\in\mathcal{J}_1$ and define $\mathcal{I}_0(j) = \bigl\{i\in\mathcal{I} :\alpha_{j,1} + \boldsymbol{\beta}_{j,1}^\top\boldsymbol{\theta}_{i,1} = \alpha_{j,2} + \boldsymbol{\beta}_{j,2}^\top\boldsymbol{\theta}_{i,2} \bigr\}$.
Substituting $\boldsymbol{\theta}_{i,1}=O\boldsymbol{\theta}_{i,2}$ gives
\begin{equation*}
    (\alpha_{j,1}-\alpha_{j,2})
    +
    (O^\top\boldsymbol{\beta}_{j,1}-\boldsymbol{\beta}_{j,2})^\top\boldsymbol{\theta}_{i,2}
    =0,
    \qquad \forall i\in\mathcal{I}_0(j).
\end{equation*}
Assumption~1 ensures $|\mathcal{I}_0(j)|\ge K+1$, and hence the only solution is
\begin{equation*}
    \alpha_{j,1}=\alpha_{j,2}
    \quad\text{and}\quad
    O^\top\boldsymbol{\beta}_{j,1}=\boldsymbol{\beta}_{j,2},
\end{equation*}
Thus, for all $j\in\mathcal{J}$ and $i\in\mathcal{I}$,
\begin{equation*}
    (\alpha_{j,1},\,\boldsymbol{\beta}_{j,1}^\top,\,\boldsymbol{\theta}_{i,1}^\top)
    =
    (\alpha_{j,2},\,(O\boldsymbol{\beta}_{j,2})^\top,\,(O\boldsymbol{\theta}_{i,2})^\top),
\end{equation*}
which establishes \eqref{eqn:eqn2_MD}.
\end{proof}

